    case TEST_PACKET:
    case TEST_FORCE_EN:
      USBx_DEVICE->DCTL &= ~(0x7U << 4);
      USBx_DEVICE->DCTL |= (uint32_t)testmode << 4;
      break;

    default:
      break;
  }

  return HAL_OK;
}
