static void SAI_Receive_IT32Bit(SAI_HandleTypeDef *hsai)
{
  /* Receive data */
  *(uint32_t *)hsai->pBuffPtr = hsai->Instance->DR;
  hsai->pBuffPtr += 4U;
  hsai->XferCount--;

  /* Check end of the transfer */
  if (hsai->XferCount == 0U)
